// expect: type mismatch
// expect: expected `Activations<4, 7>`, but `Activations<4, 3>` is given
// Two vectors of the same length at different scales are different types: they cannot be
// compared, or stand in for one another.
use tensile::Activations

pub fn same(a: Activations<4, 7>, b: Activations<4, 3>) -> bool {
    a == b
}

// expect: type mismatch
// expect: expected `Activations<3, _>`, but `Activations<2, 3>` is given
// The first layer has 2 outputs and the second expects 3 inputs.
use tensile::{Accumulators, Activations, Bias, Weights, dense}

pub fn network(
    w1: Weights<2, 4, 7>,
    b1: Bias<2, 14>,
    w2: Weights<5, 3, 6>,
    b2: Bias<5, 9>,
    x: Activations<4, 7>,
) -> Accumulators<5, 9> {
    let hidden = dense(weights: w1, x, bias: b1).requantise<11>()
    dense(weights: w2, x: hidden, bias: b2)
}

// expect: type mismatch
// expect: expected `Bias<2, 14>`, but `Bias<2, 15>` is given
// Weights with 7 fractional bits times activations with 7 give accumulators with 14, so the
// bias must have 14 as well.
use tensile::{Accumulators, Activations, Bias, Weights, dense}

pub fn layer(weights: Weights<2, 4, 7>, x: Activations<4, 7>, bias: Bias<2, 15>) -> Accumulators<2, 15> {
    dense(weights, x, bias)
}

// expect: static assertion failed
// The compile-time overflow proof rejects a layer whose worst case does not fit an int32:
// |2147483647| + 127 * 1 is larger than I32_MAX.
use tensile::{Bias, I32_MAX, Row, Weights, worst_case}

const WEIGHTS: Weights<1, 2, 7> = Weights::new([Row::pack([1, 0])])
const BIAS: Bias<1, 14> = Bias::from_raw([2147483647])

static_assert(worst_case(weights: WEIGHTS, bias: BIAS) <= I32_MAX)
